select "p".*, ST_Distance(ST_Transform(ST_GeomFromText("p"."geometry", ?), 4326)::geography, ST_SetSRID(ST_MakePoint(?, ?), 4326)::geography) as "geospatial:distance", ST_AsText(ST_Transform(ST_GeomFromText("p"."geometry", ?), 4326)) as "geospatial:4326", "p"."id"::text as "geospatial:key:1" from (select (CASE WHEN ("occurrences"."region" = ?) THEN "occurrences"."id" END) AS "id", (CASE WHEN ("occurrences"."region" = ?) THEN st_astext("occurrences"."geometry") END) AS "geometry" from "occurrences" where "occurrences"."region" = ? and ("occurrences"."geometry" && ST_MakeEnvelope(?, ?, ?, ?, ?)) and ST_DWithin(ST_Transform("occurrences"."geometry", 4326)::geography, ST_SetSRID(ST_MakePoint(?, ?), 4326)::geography, ?)) as "p" where "p"."geometry" is not null order by "geospatial:distance" asc, "p"."id" asc limit ?
